import cProfile
import pstats

def square(value):
    return value * value

def workload(count):
    total = 0
    for value in range(count):
        total += square(value)
    return total

def profile_work(count):
    profiler = cProfile.Profile()
    result = profiler.runcall(workload, count)
    stats = pstats.Stats(profiler)
    calls = 0
    for key, entry in stats.stats.items():
        if key[2] == "square":
            calls += entry[1]
    return result, calls
